contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address funder, uint256 amount) public {
        vm.assume(funder != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.assume(amount > 0);

        vm.deal(funder, amount);

        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("\x00");
        require(sent, "funding call failed");

        assert(address(c).balance == amount);

        try c.withdrawAll(address(0xBEEF)) { }
        catch {
        }

        assertTrue(address(c).balance == 0);
    }
}
